LOGIN_HTML = r'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ورود | Technamooz Control</title><style>
:root{--bg:#070708;--panel:#111114;--line:#29292f;--muted:#9b9ba5;--text:#f6f6f7;--red:#e11d48;--red2:#fb2c36;--shadow:0 24px 80px #0009}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(900px 500px at 15% 0,#4c061d55,transparent 65%),radial-gradient(700px 500px at 90% 100%,#280c1850,transparent 60%),var(--bg);color:var(--text);font-family:Tahoma,"Segoe UI",sans-serif;display:grid;place-items:center;padding:24px}.grid{position:fixed;inset:0;pointer-events:none;opacity:.12;background-image:linear-gradient(#fff 1px,transparent 1px),linear-gradient(90deg,#fff 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,black,transparent)}.card{position:relative;width:min(440px,100%);background:#111114e8;border:1px solid #ffffff18;border-radius:28px;padding:38px;box-shadow:var(--shadow);backdrop-filter:blur(20px)}.mark{display:flex;align-items:center;gap:13px;margin-bottom:36px}.logo{width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,var(--red2),#8f0d35);display:grid;place-items:center;font-size:24px;font-weight:900;box-shadow:0 10px 30px #e11d4840}.eyebrow{color:#ff6b83;font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase}.brand{font-size:22px;font-weight:800}.subtitle{color:var(--muted);font-size:12px;margin-top:4px}h1{font-size:28px;margin:0 0 8px}p{color:var(--muted);font-size:13px;line-height:1.8;margin:0 0 26px}.field{margin:15px 0}.field label{display:block;font-size:12px;color:#d8d8de;margin-bottom:8px}.input{width:100%;height:48px;padding:0 15px;border-radius:13px;border:1px solid var(--line);background:#09090b;color:var(--text);outline:none;font-size:14px}.input:focus{border-color:var(--red);box-shadow:0 0 0 4px #e11d481c}.captcha{display:flex;gap:9px}.captcha-code{width:132px;display:grid;place-items:center;border:1px dashed #ef476f99;border-radius:13px;color:#ff8299;font-size:20px;letter-spacing:5px;background:#e11d4810}.btn{width:100%;height:50px;border:0;border-radius:14px;background:linear-gradient(135deg,var(--red2),var(--red));color:white;font-weight:800;cursor:pointer;box-shadow:0 12px 26px #e11d4835}.error{min-height:20px;color:#ff8ba0;font-size:12px;margin-top:13px;text-align:center}.foot{border-top:1px solid var(--line);margin-top:28px;padding-top:18px;text-align:center;color:#656570;font-size:11px}</style></head><body><div class="grid"></div><main class="card"><div class="mark"><div class="logo">T</div><div><div class="eyebrow">SECURE CONTROL PLANE</div><div class="brand">TECHNAMOOZ</div><div class="subtitle">ساخت و مدیریت کانفیگ</div></div></div><h1>ورود امن</h1><p>برای ورود به مرکز کنترل، اطلاعات حساب و کد امنیتی را وارد کنید.</p><form id="login"><div class="field"><label>نام کاربری</label><input class="input" id="username" autocomplete="username" required></div><div class="field"><label>رمز عبور</label><input class="input" id="password" type="password" autocomplete="current-password" required></div><div class="field"><label>کد امنیتی</label><div class="captcha"><input class="input" id="captcha" inputmode="numeric" maxlength="5" required><div class="captcha-code" id="captchaCode">-----</div></div></div><button class="btn">ورود به پنل</button><div class="error" id="error"></div></form><div class="foot">Technamooz Control · Protected workspace</div></main><script>
let captcha={};async function loadCaptcha(){const r=await fetch('/api/captcha');captcha=await r.json();document.querySelector('#captchaCode').textContent=captcha.captcha_code||'-----'}document.querySelector('#login').addEventListener('submit',async e=>{e.preventDefault();const error=document.querySelector('#error');error.textContent='';try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value,captcha_id:captcha.captcha_id,captcha_code:document.querySelector('#captcha').value})});const d=await r.json();if(!r.ok)throw Error(d.detail||'ورود ناموفق بود');location.href='__ADMIN_DASHBOARD_PATH__'}catch(x){error.textContent=x.message;loadCaptcha()}});loadCaptcha();</script></body></html>'''

DASHBOARD_HTML = r'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control Plane | Technamooz</title><style>
:root{--bg:#08080a;--surface:#101013;--surface2:#15151a;--line:#292930;--text:#f7f7f8;--muted:#92929d;--red:#e11d48;--red2:#fb2c36;--green:#26d98b;--shadow:0 18px 60px #0008}*{box-sizing:border-box}body{margin:0;background:radial-gradient(850px 520px at 100% 0,#3b081c42,transparent 65%),var(--bg);color:var(--text);font-family:Tahoma,"Segoe UI",sans-serif}.app{display:flex;min-height:100vh}.side{width:252px;position:fixed;inset:0 auto 0 0;background:#0c0c0f;border-right:1px solid var(--line);padding:24px 16px;display:flex;flex-direction:column;z-index:5}.brand{display:flex;align-items:center;gap:10px;padding:4px 9px 30px}.logo{width:40px;height:40px;border-radius:13px;display:grid;place-items:center;font-weight:900;font-size:20px;background:linear-gradient(135deg,var(--red2),#8f0d35);box-shadow:0 8px 24px #e11d4840}.brand b{font-size:17px}.brand small{display:block;color:var(--muted);font-size:10px;margin-top:3px;letter-spacing:1px}.nav-title{color:#5f5f69;font-size:10px;font-weight:bold;padding:15px 12px 8px;letter-spacing:1px}.nav button{width:100%;border:0;background:transparent;color:#9e9ea7;text-align:right;padding:12px;border-radius:11px;cursor:pointer;font:inherit;font-size:12px;display:flex;align-items:center;gap:10px}.nav button:hover,.nav button.active{background:#e11d4818;color:#fff}.nav button.active{border-right:3px solid var(--red)}.side-foot{margin-top:auto;border-top:1px solid var(--line);padding:15px 10px;color:var(--muted);font-size:10px;line-height:2}.main{margin-left:252px;width:calc(100% - 252px);padding:28px clamp(20px,4vw,52px);max-width:1600px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:30px}.crumb{color:var(--muted);font-size:12px}.crumb strong{color:var(--text);font-size:20px;display:block;margin-top:7px}.top-actions{display:flex;gap:9px}.icon-btn,.btn{border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:11px;padding:10px 14px;cursor:pointer;font:inherit;font-size:12px}.btn.primary{background:linear-gradient(135deg,var(--red2),var(--red));border:0;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:18px}.metric,.panel{background:linear-gradient(145deg,#141418dd,#0e0e11dd);border:1px solid #ffffff12;border-radius:18px;box-shadow:var(--shadow)}.metric{padding:19px;position:relative;overflow:hidden}.metric:after{content:"";position:absolute;bottom:0;right:0;width:70px;height:3px;background:var(--red)}.metric .label{color:var(--muted);font-size:11px}.metric .value{font-size:28px;font-weight:800;margin:11px 0 5px}.metric .hint{font-size:10px;color:#6e6e78}.grid2{display:grid;grid-template-columns:1.45fr 1fr;gap:16px}.panel{padding:21px;margin-bottom:16px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.panel-head h2{font-size:15px;margin:0}.panel-head span{color:var(--muted);font-size:11px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:12px}.table th{color:#6f6f79;text-align:right;font-size:10px;font-weight:normal;padding:10px 8px;border-bottom:1px solid var(--line)}.table td{padding:13px 8px;border-bottom:1px solid #ffffff08;white-space:nowrap}.badge{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border-radius:7px;background:#ffffff0a;color:#c9c9d0;font-size:10px}.badge:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--green)}.badge.off:before{background:#74747e}.protocol{color:#ff718c;font-size:10px}.mini{padding:6px 8px;border:1px solid var(--line);background:transparent;border-radius:7px;color:#bdbdc6;cursor:pointer;font-size:10px}.empty{padding:32px;text-align:center;color:var(--muted);font-size:12px}.activity{display:flex;flex-direction:column;gap:13px}.event{display:flex;gap:10px;align-items:flex-start;font-size:11px}.event i{width:7px;height:7px;border-radius:50%;background:var(--red);margin-top:4px;flex:none}.event small{display:block;color:#62626d;margin-top:4px}.view{display:none}.view.active{display:block}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.field label{display:block;color:#aaaab4;font-size:11px;margin-bottom:7px}.input,select{width:100%;height:42px;border:1px solid var(--line);border-radius:10px;background:#09090b;color:var(--text);padding:0 11px;outline:none;font:inherit;font-size:12px}.dialog-foot{display:flex;justify-content:flex-start;gap:9px;margin-top:22px}.modal{position:fixed;inset:0;background:#000b;display:none;place-items:center;padding:20px;z-index:20}.modal.open{display:grid}.dialog{width:min(620px,100%);max-height:90vh;overflow:auto;background:#141418;border:1px solid #ffffff18;border-radius:21px;padding:24px}.dialog h2{margin:0 0 20px;font-size:17px}.toast{position:fixed;bottom:22px;right:22px;z-index:30;background:#202026;border:1px solid var(--line);border-right:3px solid var(--green);padding:12px 16px;border-radius:11px;font-size:12px;display:none}.toast.show{display:block}@media(max-width:900px){.side{width:70px;padding:18px 10px}.brand{justify-content:center;padding:4px 0 25px}.brand>div:not(.logo),.nav-title,.nav button span,.side-foot{display:none}.nav button{justify-content:center}.main{margin-left:70px;width:calc(100% - 70px);padding:22px 16px}.metrics{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}}@media(max-width:560px){.top{align-items:flex-start;flex-direction:column}.metrics{gap:8px}.metric{padding:14px}.metric .value{font-size:22px}.form-grid{grid-template-columns:1fr}.top-actions{width:100%}.top-actions .btn{flex:1}.table{min-width:680px}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><div class="logo">T</div><div><b>TECHNAMOOZ</b><small>CONTROL PLANE</small></div></div><div class="nav-title">WORKSPACE</div><nav class="nav"><button class="active" data-view="overview">▦ <span>نمای کلی</span></button><button data-view="links">◈ <span>کانفیگ‌ها</span></button><button data-view="subs">◎ <span>گروه‌های اشتراک</span></button><button data-view="connections">⌁ <span>اتصال‌های زنده</span></button><button data-view="settings">⚙ <span>تنظیمات</span></button></nav><div class="side-foot">نسخه 2.0 Control Plane<br><span style="color:var(--green)">● سیستم آنلاین</span></div></aside><main class="main"><header class="top"><div class="crumb">TECHNAMOOZ / <span id="section">OVERVIEW</span><strong id="title">نمای کلی سیستم</strong></div><div class="top-actions"><button class="icon-btn" onclick="reloadAll()">↻ بروزرسانی</button><button class="btn primary" onclick="openModal('linkModal')">＋ کانفیگ جدید</button></div></header><section id="overview" class="view active"><div class="metrics"><div class="metric"><div class="label">کانفیگ‌های فعال</div><div class="value" id="mLinks">—</div><div class="hint">از کل کانفیگ‌ها</div></div><div class="metric"><div class="label">گروه‌های اشتراک</div><div class="value" id="mSubs">—</div><div class="hint">اشتراک سازمان‌یافته</div></div><div class="metric"><div class="label">اتصال‌های زنده</div><div class="value" id="mConn">—</div><div class="hint">در لحظه</div></div><div class="metric"><div class="label">ترافیک مصرفی</div><div class="value" id="mTraffic">—</div><div class="hint">از زمان شروع</div></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>آخرین کانفیگ‌ها</h2><span id="lastUpdated">در حال بارگذاری...</span></div><div class="table-wrap"><table class="table"><thead><tr><th>نام</th><th>پروتکل</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody id="recentLinks"></tbody></table></div></div><div class="panel"><div class="panel-head"><h2>رویدادهای سیستم</h2><span>LIVE</span></div><div class="activity" id="activity"></div></div></div></section><section id="links" class="view"><div class="panel"><div class="panel-head"><h2>مدیریت کانفیگ‌ها</h2><button class="btn primary" onclick="openModal('linkModal')">＋ ساخت کانفیگ</button></div><div class="table-wrap"><table class="table"><thead><tr><th>نام</th><th>پروتکل</th><th>گروه</th><th>مصرف</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody id="allLinks"></tbody></table></div></div></section><section id="subs" class="view"><div class="panel"><div class="panel-head"><h2>گروه‌های اشتراک</h2><button class="btn primary" onclick="openModal('subModal')">＋ گروه جدید</button></div><div class="table-wrap"><table class="table"><thead><tr><th>نام گروه</th><th>تعداد</th><th>آدرس عمومی</th><th>عملیات</th></tr></thead><tbody id="allSubs"></tbody></table></div></div></section><section id="connections" class="view"><div class="panel"><div class="panel-head"><h2>اتصال‌های زنده</h2><span>اتصال‌های فعال relay</span></div><div class="table-wrap"><table class="table"><thead><tr><th>شناسه</th><th>IP</th><th>حمل‌ونقل</th><th>زمان</th><th>حجم</th></tr></thead><tbody id="allConnections"></tbody></table></div></div></section><section id="settings" class="view"><div class="panel"><div class="panel-head"><h2>تنظیمات حساب</h2></div><div class="form-grid"><div class="field"><label>نام کاربری جدید</label><input class="input" id="newUser"></div><div class="field"><label>رمز فعلی</label><input class="input" id="oldPass" type="password"></div><div class="field"><label>رمز جدید</label><input class="input" id="newPass" type="password"></div></div><div class="dialog-foot"><button class="btn primary" onclick="saveCredentials()">ذخیره تغییرات</button><button class="btn" onclick="logout()">خروج از حساب</button></div></div><div class="panel"><div class="panel-head"><h2>پشتیبان‌گیری</h2><span>فایل state شامل secrets نمی‌شود</span></div><button class="btn" onclick="downloadBackup()">دانلود Backup</button></div></section></main></div><div class="modal" id="linkModal"><div class="dialog"><h2>ساخت کانفیگ جدید</h2><div class="form-grid"><div class="field"><label>نام کانفیگ</label><input class="input" id="fLabel" placeholder="مثلاً همراه اول - 01"></div><div class="field"><label>پروتکل</label><select id="fProtocol"><option value="vless-ws">VLESS WebSocket</option><option value="trojan-ws">Trojan WebSocket</option><option value="xhttp-packet-up">XHTTP Packet-Up</option><option value="xhttp-stream-up">XHTTP Stream-Up</option></select></div><div class="field"><label>پورت</label><input class="input" id="fPort" value="443" type="number"></div><div class="field"><label>گروه اشتراک</label><select id="fSub"><option value="">بدون گروه</option></select></div><div class="field"><label>مدت انقضا (روز)</label><input class="input" id="fDays" type="number"></div><div class="field"><label>محدودیت حجم (مثلاً 20GB)</label><input class="input" id="fLimit"></div></div><div class="dialog-foot"><button class="btn primary" onclick="createLink()">ساخت کانفیگ</button><button class="btn" onclick="closeModal('linkModal')">انصراف</button></div></div></div><div class="modal" id="subModal"><div class="dialog"><h2>ساخت گروه اشتراک</h2><div class="form-grid"><div class="field"><label>نام گروه</label><input class="input" id="sName"></div><div class="field"><label>رمز گروه (اختیاری)</label><input class="input" id="sPassword" type="password"></div><div class="field"><label>توضیحات</label><input class="input" id="sDesc"></div></div><div class="dialog-foot"><button class="btn primary" onclick="createSub()">ساخت گروه</button><button class="btn" onclick="closeModal('subModal')">انصراف</button></div></div></div><div class="toast" id="toast"></div><script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let links=[],subs=[];const loginPath='__ADMIN_LOGIN_PATH__';function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s,ok=true){const t=$('#toast');t.textContent=s;t.style.borderRightColor=ok?'var(--green)':'var(--red2)';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}function openModal(id){$('#'+id).classList.add('open');loadSubsSelect()}function closeModal(id){$('#'+id).classList.remove('open')}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt});if(r.status===401){location.href=loginPath;throw Error('نشست منقضی شده است')}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'خطا در ارتباط با سرور');return d}$$('.nav button').forEach(b=>b.onclick=()=>{const v=b.dataset.view;$$('.nav button').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));$('#section').textContent=v.toUpperCase();$('#title').textContent={overview:'نمای کلی سیستم',links:'مدیریت کانفیگ‌ها',subs:'گروه‌های اشتراک',connections:'اتصال‌های زنده',settings:'تنظیمات'}[v]||v;if(v==='connections')loadConnections()});function row(l,full=false){return `<tr><td><b>${esc(l.label||'بدون نام')}</b><br><small class="protocol">${esc(l.uuid||'').slice(0,12)}…</small></td><td class="protocol">${esc(l.protocol)}</td>${full?`<td>${esc((subs.find(s=>s.sub_id===l.sub_id)||{}).name||'—')}</td><td>${esc(l.used_fmt||'0 B')}</td>`:''}<td><span class="badge ${l.active===false?'off':''}">${l.active===false?'غیرفعال':'فعال'}</span></td><td><button class="mini" onclick="toggleLink('${l.uuid}',${l.active===false})">${l.active===false?'فعال':'خاموش'}</button> <button class="mini" onclick="copyText('${esc(l.vless_link||'')}')">کپی</button></td></tr>`}async function loadLinks(){const d=await api('/api/links');links=d.links||[];$('#allLinks').innerHTML=links.length?links.map(x=>row(x,true)).join(''):'<tr><td colspan="6" class="empty">هنوز کانفیگی ساخته نشده است.</td></tr>';$('#recentLinks').innerHTML=links.slice(0,7).map(x=>row(x)).join('')||'<tr><td colspan="4" class="empty">داده‌ای وجود ندارد.</td></tr>';$('#mLinks').textContent=links.filter(x=>x.active!==false&&!x.expired).length+'/'+links.length;$('#lastUpdated').textContent='آخرین بروزرسانی: همین حالا'}async function loadSubs(){const d=await api('/api/subs');subs=d.subs||[];$('#allSubs').innerHTML=subs.length?subs.map(s=>`<tr><td><b>${esc(s.name)}</b><br><small>${esc(s.desc||'')}</small></td><td>${(s.link_ids||[]).length}</td><td><button class="mini" onclick="copyText('${esc(s.sub_url||'')}')">کپی لینک</button></td><td><button class="mini" onclick="deleteSub('${s.sub_id}')">حذف</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">هنوز گروهی ساخته نشده است.</td></tr>';$('#mSubs').textContent=subs.length}function loadSubsSelect(){$('#fSub').innerHTML='<option value="">بدون گروه</option>'+subs.map(s=>`<option value="${esc(s.sub_id)}">${esc(s.name)}</option>`).join('')}async function loadConnections(){const d=await api('/api/connections');const cs=d.connections||[];$('#allConnections').innerHTML=cs.length?cs.map(c=>`<tr><td>${esc(c.conn_id||'—')}</td><td>${esc(c.ip||'—')}</td><td>${esc(c.transport||'—')}</td><td>${esc(c.connected_at||'—')}</td><td>${esc(c.bytes||0)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">اتصال زنده‌ای وجود ندارد.</td></tr>';$('#mConn').textContent=cs.length}async function loadActivity(){const d=await api('/api/activity');const a=d.activity||[];$('#activity').innerHTML=a.slice(0,8).map(x=>`<div class="event"><i></i><div>${esc(x.message)}<small>${esc(x.time||'')}</small></div></div>`).join('')||'<div class="empty">رویدادی ثبت نشده است.</div>'}async function loadSystem(){try{const d=await api('/api/system');$('#mTraffic').textContent=d.traffic||d.total_traffic||'0 B'}catch(e){$('#mTraffic').textContent='—'}}async function reloadAll(){try{await Promise.all([loadLinks(),loadSubs(),loadActivity(),loadSystem()]);toast('اطلاعات بروزرسانی شد')}catch(e){toast(e.message,false)}}async function createLink(){try{await api('/api/links',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({label:$('#fLabel').value,protocol:$('#fProtocol').value,port:$('#fPort').value,sub_id:$('#fSub').value,expires_days:$('#fDays').value||0,limit_value:$('#fLimit').value||0})});closeModal('linkModal');toast('کانفیگ ساخته شد');reloadAll()}catch(e){toast(e.message,false)}}async function createSub(){try{await api('/api/subs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#sName').value,desc:$('#sDesc').value,password:$('#sPassword').value})});closeModal('subModal');toast('گروه ساخته شد');reloadAll()}catch(e){toast(e.message,false)}}async function toggleLink(uid,active){try{await api('/api/links/'+uid,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({active})});toast('وضعیت بروزرسانی شد');loadLinks()}catch(e){toast(e.message,false)}}async function deleteSub(id){if(!confirm('این گروه حذف شود؟'))return;try{await api('/api/subs/'+id,{method:'DELETE'});toast('گروه حذف شد');reloadAll()}catch(e){toast(e.message,false)}}async function saveCredentials(){try{await api('/api/change-credentials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#newUser').value,current_password:$('#oldPass').value,new_password:$('#newPass').value})});toast('اطلاعات ورود ذخیره شد')}catch(e){toast(e.message,false)}}async function downloadBackup(){const d=await api('/api/backup');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='technamooz-backup.json';a.click()}async function copyText(s){try{await navigator.clipboard.writeText(s);toast('کپی شد')}catch(e){toast('کپی ناموفق بود',false)}}async function logout(){await fetch('/api/logout',{method:'POST'});location.href=loginPath}reloadAll();</script></body></html>'''


def _inject(html: str, login_path: str, dashboard_path: str) -> str:
    return html.replace('__ADMIN_LOGIN_PATH__', login_path).replace('__ADMIN_DASHBOARD_PATH__', dashboard_path)


def get_login_html(login_path: str, dashboard_path: str) -> str:
    return _inject(LOGIN_HTML, login_path, dashboard_path)


def get_dashboard_html(login_path: str, dashboard_path: str) -> str:
    html = _inject(DASHBOARD_HTML, login_path, dashboard_path)
    telegram_panel = '''<div class="panel"><div class="panel-head"><h2>ربات Telegram</h2><span id="tgStatus">در حال بررسی...</span></div><div class="form-grid"><div class="field"><label>Bot Token</label><input class="input" id="tgToken" type="password" placeholder="برای حفظ امنیت خالی بگذارید"></div><div class="field"><label>Admin IDs</label><input class="input" id="tgAdmins" placeholder="123456789,987654321"></div><div class="field"><label><input id="tgEnabled" type="checkbox" style="width:auto;height:auto;margin-left:7px"> فعال باشد</label></div></div><div class="dialog-foot"><button class="btn primary" onclick="saveTelegram()">ذخیره تنظیمات</button><button class="btn" onclick="loadTelegram()">بروزرسانی وضعیت</button></div></div>'''
    html = html.replace('</section></main>', telegram_panel + '</section></main>')
    telegram_script = '''async function loadTelegram(){try{const d=await api('/api/telegram/status');document.querySelector('#tgStatus').textContent=d.enabled?'ONLINE':'OFFLINE';document.querySelector('#tgEnabled').checked=!!d.enabled;if(d.admin_ids)document.querySelector('#tgAdmins').value=d.admin_ids}catch(e){document.querySelector('#tgStatus').textContent='ERROR'}}async function saveTelegram(){try{await api('/api/telegram/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:document.querySelector('#tgToken').value,admin_ids:document.querySelector('#tgAdmins').value,enabled:document.querySelector('#tgEnabled').checked})});toast('تنظیمات Telegram ذخیره شد');loadTelegram()}catch(e){toast(e.message,false)}}loadTelegram();'''
    return html.replace('</script></body>', telegram_script + '</script></body>')


def get_public_page_html(uuid_key: str) -> str:
    key = escape(uuid_key, quote=True)
    return f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>اشتراک Technamooz</title><style>:root{{--bg:#08080a;--panel:#141418;--line:#292930;--text:#f7f7f8;--muted:#9999a4;--red:#e11d48}}*{{box-sizing:border-box}}body{{margin:0;min-height:100vh;background:radial-gradient(800px 400px at 50% 0,#4b071d55,transparent 70%),var(--bg);color:var(--text);font-family:Tahoma,sans-serif;display:grid;place-items:center;padding:20px}}.card{{width:min(560px,100%);background:var(--panel);border:1px solid #ffffff16;border-radius:24px;padding:28px;box-shadow:0 20px 70px #0009}}.logo{{width:46px;height:46px;border-radius:14px;background:linear-gradient(135deg,#fb2c36,var(--red));display:grid;place-items:center;font-weight:900;font-size:22px}}h1{{font-size:22px;margin:18px 0 8px}}p,.muted{{color:var(--muted);font-size:12px;line-height:1.9}}input,button{{height:44px;border-radius:11px;border:1px solid var(--line);background:#09090b;color:var(--text);padding:0 13px;font:inherit}}input{{width:100%;margin:10px 0}}button{{background:var(--red);border:0;cursor:pointer;width:100%;font-weight:bold}}.item{{border-top:1px solid var(--line);padding:16px 0}}.item b{{font-size:13px}}.copy{{margin-top:9px;background:#e11d4818;border:1px solid #e11d4860;color:#ff8da2}}#error{{color:#ff8da2;font-size:12px;min-height:20px}}</style></head><body><main class="card"><div class="logo">T</div><h1>اشتراک کانفیگ</h1><p id="name">در حال بارگذاری...</p><div id="gate"><input id="pw" type="password" placeholder="رمز اشتراک در صورت وجود"><button onclick="load()">نمایش اشتراک</button><div id="error"></div></div><div id="items"></div></main><script>const key="{key}";async function load(){{const pw=document.querySelector('#pw').value;const r=await fetch('/api/public/sub/'+key+(pw?'?pw='+encodeURIComponent(pw):''));const d=await r.json();document.querySelector('#name').textContent=d.name||'اشتراک Technamooz';if(d.locked){{document.querySelector('#error').textContent='رمز اشتراک صحیح نیست یا وارد نشده است';return}}document.querySelector('#gate').style.display='none';document.querySelector('#items').innerHTML=(d.links||[]).map(x=>`<div class="item"><b>${{x.label||'کانفیگ'}}</b><p>${{x.protocol}} · ${{x.used_fmt||'0 B'}} مصرف</p><button class="copy" onclick="navigator.clipboard.writeText('${{String(x.vless_link||'').replaceAll("'","\\'")}}')">کپی لینک اتصال</button></div>`).join('')||'<p>کانفیگی برای این اشتراک وجود ندارد.</p>'}}load();</script></body></html>'''
